@staticmethod
def _stop_services() -> None:
    """Stop the hermes-agent systemd service so it doesn't recreate files
    during uninstall (#453). Best-effort — missing systemctl or a missing
    unit is not an error; the uninstall proceeds regardless."""
    unit = "hal0-agent@hermes.service"
    if shutil.which("systemctl") is None:
        return
    try:
        subprocess.run(  # nosec B603 — known-safe argv
            ["systemctl", "stop", "--no-block", unit],
            check=False,
            capture_output=True,
            timeout=5,
        )
    except (OSError, subprocess.SubprocessError):
        pass

